import 'package:flutter_test/flutter_test.dart';
import 'package:smart_reading_buddy/core/services/numbers/level_config.dart';
import 'package:smart_reading_buddy/core/services/numbers/level_progress.dart';
import 'package:smart_reading_buddy/features/numbers/services/question_generator.dart';

/// LevelProgressRules (core/) decides "playable" from ActivityType.all,
/// since core/ can't import the Numbers generators. This keeps that list
/// and the generators in sync: every listed type must be generated by
/// QuestionGenerator, or be Number Match (MatchBoardGenerator).
void main() {
  test('every ActivityType has a generator', () {
    for (final type in ActivityType.all) {
      expect(
        QuestionGenerator.supports(type) || type == ActivityType.numberMatch,
        isTrue,
        reason: '$type is in ActivityType.all but nothing generates it',
      );
    }
  });

  test('isPlayable matches the generators exactly', () {
    for (final type in [...ActivityType.all, 'juggling']) {
      final level = LevelConfig.fromJson({
        'id': 'x', 'grade': 3, 'track': 'basic', 'level': 1, 'title': 'x', 'activityType': type,
      });
      expect(
        LevelProgressRules.isPlayable(level),
        QuestionGenerator.supports(type) || type == ActivityType.numberMatch,
        reason: type,
      );
    }
  });
}
